.threshold-label {
  font-size: 13px;
  font-weight: 600;
}
.threshold-label output {
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}
.threshold-control input {
  display: block;
  width: 100%;
  height: 28px;
  margin: 6px 0 0;
  accent-color: var(--accent);
  cursor: pointer;
}
.threshold-control input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}
.threshold-scale,
#threshold-help {
  color: var(--muted);
  font-size: 12px;
}
#threshold-help {
  margin: 10px 0 0;
  line-height: 1.5;
}

.entity-name {
  text-decoration: none;
}
.entity-name:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.detail-page {
  width: min(100%, 1000px);
  margin-top: 40px;
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

export function backToSearch(params: Pick<URLSearchParams, "get">): string {
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;

